import math
import itertools
import time
import numpy as np
from scipy.optimize import minimize_scalar

N = 11
D = math.sqrt(3.0)
SQ3 = math.sqrt(3.0)
EPS = 1e-9
DEADLINE = 150.0
MARGIN = 8.0

# Vertices of a unit hexagon (side 1), flat-top, center (0,0), vertex at angle 0
HEX_VERTS = np.array([[math.cos(i * math.pi / 3), math.sin(i * math.pi / 3)] for i in range(6)])

# All 11-cell free polyhexes (generated by canonical enumeration)
def gen_polyhexes(n):
    def key(cells):
        return tuple(sorted((round(q, 6), round(r, 6)) for q, r in cells))
    def neighbors(c):
        q, r = c
        return [(q + dq, r + dr) for dq, dr in ((1, 0), (-1, 0), (0, 1), (0, -1), (1, -1), (-1, 1))]
    def canon(cells):
        cells = list(cells)
        best = None
        for c in cells:
            q, r = c
            trans = [(a - q, b - r) for a, b in cells]
            rot = [(trans[i][0], trans[i][1]) for i in range(len(trans))]
            for k in range(6):
                rot = [(x, y) for x, y in rot]
                rot = [(x - y, x + y) for x, y in rot]
                kk = tuple(sorted((round(a, 6), round(b, 6)) for a, b in rot))
                if best is None or kk < best:
                    best = kk
        return best
    seen = set()
    out = []
    def rec(cells):
        if len(cells) == n:
            ck = canon(cells)
            if ck not in seen:
                seen.add(ck)
                out.append([ck[0], ck[1], ck[2], ck[3], ck[4]])
            return
        cells = sorted(cells)
        last = cells[-1]
        cand = set()
        for nb in neighbors(last):
            if nb not in cells:
                cand.add(nb)
        for nb in sorted(cand):
            rec(cells + [nb])
    rec([(0, 0)])
    return out

POLYHEXES = gen_polyhexes(N)

def axial_to_cartesian(ax):
    q = np.asarray([c[0] for c in ax], dtype=float)
    r = np.asarray([c[1] for c in ax], dtype=float)
    x = D * (q + r * 0.5)
    y = D * (SQ3 / 2.0) * r
    return np.column_stack([x, y])

# Precompute centers for each topology
TOP_CENTERS = [axial_to_cartesian(ax) for ax in POLYHEXES]

def calc_S(theta, centers, offset=(0.0, 0.0)):
    c = centers + np.asarray(offset, dtype=float)
    angles = theta + np.arange(6) * (math.pi / 3)
    normals = np.column_stack([np.cos(angles), np.sin(angles)])
    allv = (c[:, None, :] + HEX_VERTS[None, :, :]).reshape(-1, 2)
    projs = np.abs(allv @ normals.T)
    return (2.0 / SQ3) * float(np.max(projs))

def scan_theta(centers):
    coarse = np.linspace(0.0, math.pi / 6, 40)
    vals = np.array([calc_S(t, centers) for t in coarse])
    mi = int(np.argmin(vals))
    lo = coarse[max(0, mi - 1)]
    hi = coarse[min(len(coarse) - 1, mi + 1)]
    try:
        res = minimize_scalar(lambda t: calc_S(t, centers), bounds=(lo, hi), method='bounded',
                              options={'xatol': 1e-8})
        if res.success and res.fun < vals[mi]:
            return float(res.fun), float(res.x)
    except Exception:
        pass
    return float(vals[mi]), float(coarse[mi])

def anneal(centers, theta0):
    import random
    random.seed(12345)
    T = 0.05
    best = calc_S(theta0, centers)
    cx = cy = 0.0
    t = theta0
    for i in range(4000):
        T *= 0.9985
        nx = cx + random.gauss(0, 0.15)
        ny = cy + random.gauss(0, 0.15)
        nt = t + random.gauss(0, 0.02)
        fn = calc_S(nt, centers, (nx, ny))
        if fn < best or random.random() < math.exp(-(fn - best) / max(T, 1e-9)):
            cx, cy, t, best = nx, ny, nt, fn
    # local polish
    for _ in range(3):
        try:
            r1 = minimize_scalar(lambda tt: calc_S(tt, centers, (cx, cy)),
                                 bounds=(t - math.pi / 12, t + math.pi / 12), method='bounded',
                                 options={'xatol': 1e-9})
            if r1.success:
                t = float(r1.x)
        except Exception:
            pass
        try:
            r2 = minimize_scalar(lambda v: calc_S(t, centers, (v, cy)),
                                 bounds=(cx - 1.0, cx + 1.0), method='bounded', options={'xatol': 1e-9})
            if r2.success:
                cx = float(r2.x)
        except Exception:
            pass
        try:
            r3 = minimize_scalar(lambda v: calc_S(t, centers, (cx, v)),
                                 bounds=(cy - 1.0, cy + 1.0), method='bounded', options={'xatol': 1e-9})
            if r3.success:
                cy = float(r3.x)
        except Exception:
            pass
    best = calc_S(t, centers, (cx, cy))
    return best, t, cx, cy

def construct():
    t0 = time.time()

    # Phase 1: evaluate all topologies, keep best 30
    results = []
    for idx, centers in enumerate(TOP_CENTERS):
        if time.time() > DEADLINE - MARGIN:
            break
        S, th = scan_theta(centers)
        results.append((S, th, idx))
    results.sort(key=lambda x: x[0])

    # Phase 2: anneal the best few
    best = float('inf')
    best_data = None
    for (S, th, idx) in results[:15]:
        if time.time() > DEADLINE - MARGIN:
            break
        S2, t2, cx, cy = anneal(TOP_CENTERS[idx], th)
        if S2 < best:
            best = S2
            best_data = (t2, cx, cy, idx)

    if best_data is None:
        # fallback straight line
        inner = [[4.0 * k, 0.0, 0.0] for k in range(-(N // 2), N - N // 2)]
        return inner, (0.0, 0.0), 40.0, 0.0

    t2, cx, cy, idx = best_data
    centers = TOP_CENTERS[idx] + np.array([cx, cy])
    inner = [[float(x), float(y), 0.0] for x, y in centers]
    return inner, (0.0, 0.0), float(best + EPS), float(math.degrees(t2))
